/// <reference types="bun-types" />
/**
 * Bundle three.js and the preview loaders into one ES module and write it as
 * a string export. The server serves it at `/three-kit.js`, and the app
 * imports it only when a preview needs it, since plugin app bundles have no
 * code splitting and every Review visit would otherwise load it.
 */
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const here = (path: string) => fileURLToPath(new URL(path, import.meta.url));
const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
const manifest = JSON.parse(
  await readFile(createRequire(import.meta.url).resolve("three/package.json"), "utf8"),
) as { version: string };
const entry = await readFile(here("./three-kit-entry.ts"), "utf8");
const result = await Bun.build({
  entrypoints: [here("./three-kit-entry.ts")],
  format: "esm",
  target: "browser",
  minify: true,
});
if (!result.success) throw new AggregateError(result.logs, "three.js bundle failed");
const source = await result.outputs[0]!.text();
await writeFile(
  here("./three-kit.ts"),
  `// Generated by \`bun run vendor:three\` from three ${manifest.version}. Do not edit.\n` +
    `export const THREE_KIT_VERSION = ${JSON.stringify(manifest.version)};\n` +
    `export const THREE_KIT_ENTRY_HASH = ${JSON.stringify(sha256(entry))};\n` +
    `export const THREE_KIT_ETAG = ${JSON.stringify(`"${sha256(source).slice(0, 32)}"`)};\n` +
    `export default ${JSON.stringify(source)};\n`,
);
console.log(`Wrote vendor/three-kit.ts (${source.length} bytes, three ${manifest.version})`);
